begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.k(n integer) returns uuid language sql immutable as $$select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.k(n),'onboarding-draft-'||n||'@example.test','{}' from generate_series(1,4)n;
insert into public.organizations(id,name,created_by) values(pg_temp.k(10),'Setup Alpha',pg_temp.k(1)),(pg_temp.k(11),'Setup Beta',pg_temp.k(4));
insert into public.memberships(organization_id,user_id,role) values(pg_temp.k(10),pg_temp.k(1),'OWNER'),(pg_temp.k(10),pg_temp.k(2),'MEMBER'),(pg_temp.k(10),pg_temp.k(3),'VIEWER'),(pg_temp.k(11),pg_temp.k(4),'OWNER');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.k(4)::text,true);
select public.save_onboarding_draft(pg_temp.k(11),'company','{"companyName":["Foreign setup draft"]}',null,null);
select set_config('request.jwt.claim.sub',pg_temp.k(1)::text,true);
select is((select count(*)::integer from public.onboarding_drafts),0,'manager sees no foreign draft');
select throws_ok($$select public.read_onboarding_draft(pg_temp.k(11),'company')$$,'42501',null,'foreign draft read denied');
select throws_ok($$select public.save_onboarding_draft(pg_temp.k(11),'company','{}',null,null)$$,'42501',null,'foreign draft write denied');
select throws_ok($$select public.save_onboarding_draft(pg_temp.k(10),'product','{}',null,null)$$,'22023',null,'draft does not bypass step order');
select lives_ok($$select public.save_onboarding_draft(pg_temp.k(10),'company','{"companyName":["A"]}',null,null)$$,'incomplete field is resumable before canonical validation');
select is((select fields->'companyName'->>0 from public.read_onboarding_draft(pg_temp.k(10),'company')),'A','partial draft survives a fresh read');
select is((select count(*)::integer from public.company_profiles),0,'autosave is not a canonical Company write');
select is((select count(*)::integer from public.onboarding_progress),0,'autosave does not advance progress');
select throws_ok($$select public.save_onboarding_draft(pg_temp.k(10),'company','{"companyName":["Another tab"]}',null,null)$$,'PT409',null,'two initial tabs cannot silently overwrite a saved draft');
select throws_ok($$select public.save_onboarding_draft(pg_temp.k(10),'company','{"secretField":["unsupported"]}',null,(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'company')))$$,'22023',null,'draft fields are whitelisted');
select throws_ok($$select public.commit_onboarding_step(pg_temp.k(10),'company','{"companyName":"A"}',null,(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'company')))$$,'22023',null,'Continue validates all required content');
select is((select fields->'companyName'->>0 from public.onboarding_drafts where organization_id=pg_temp.k(10)),'A','invalid commit retains draft');
select throws_ok($$select public.finish_company_onboarding(pg_temp.k(10))$$,'22023',null,'cannot finish missing canonical steps');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'company','{"companyName":"Fictional companyName context","industry":"Fictional industry context","instagram":"","primaryMarket":"","shortDescription":"Fictional shortDescription context","stage":"IDEA","website":""}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'company')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'company')))$$,'atomic company commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),2,'company records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='company'),0,'company consumes its draft atomically');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'problem','{"affectedAudience":"","coreInsight":"","currentAlternatives":[],"problemImportance":"","problemStatement":"Fictional problemStatement context","startupIdea":"Fictional startupIdea context"}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'problem')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'problem')))$$,'atomic problem commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),3,'problem records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='problem'),0,'problem consumes its draft atomically');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'product','{"coreCapabilities":[],"differentiators":[],"nearTermObjective":"","productConcept":"Fictional productConcept context","productStatus":"CONCEPT","valueProposition":"Fictional valueProposition context"}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'product')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'product')))$$,'atomic product commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),4,'product records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='product'),0,'product consumes its draft atomically');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'audience','{"attentionChannels":[],"characteristics":[],"description":"Fictional description context","goals":[],"motivations":[],"name":"Fictional name context","objections":[],"painPoints":[]}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'audience')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'audience')))$$,'atomic audience commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),5,'audience records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='audience'),0,'audience consumes its draft atomically');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'positioning-brand','{"avoid":[],"brandStatus":"UNDECIDED","communicationTraits":[],"desiredEmotions":[],"desiredPerception":"","emphasize":[],"keyPromise":"","personalityTraits":[],"positioningCategory":"","positioningDifference":"Fictional positioningDifference context","primaryColors":[],"reasonsToBelieve":[],"statusQuo":"","toneOfVoice":[],"visualDirection":""}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'positioning-brand')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'positioning-brand')))$$,'atomic positioning-brand commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),6,'positioning-brand records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='positioning-brand'),0,'positioning-brand consumes its draft atomically');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'marketing','{"contentFocus":[],"desiredAudienceAction":"","marketingStage":"NOT_STARTED","notes":"","primaryChannels":["Fictional primaryChannels context"],"primaryObjective":"AWARENESS","secondaryObjectives":[]}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'marketing')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'marketing')))$$,'atomic marketing commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),7,'marketing records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='marketing'),0,'marketing consumes its draft atomically');
select lives_ok($$select public.commit_onboarding_step(pg_temp.k(10),'competitors','{"competitors":[]}'::jsonb,(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'competitors')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'competitors')))$$,'atomic competitors commit');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),8,'competitors records durable absolute progress');
select is((select count(*)::integer from public.onboarding_drafts where organization_id=pg_temp.k(10) and step='competitors'),0,'competitors consumes its draft atomically');
select lives_ok($$select public.save_onboarding_draft(pg_temp.k(10),'company','{"companyName":["A revised draft"]}',(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'company')),null)$$,'completed step can keep an unfinished review edit');
select throws_ok($$select public.finish_company_onboarding(pg_temp.k(10))$$,'22023',null,'Review must resolve outstanding saved drafts');
update public.company_profiles set short_description='A separate confirmed company update',updated_by=pg_temp.k(1) where organization_id=pg_temp.k(10);
select ok((select conflicted from public.read_onboarding_draft(pg_temp.k(10),'company')),'concurrent canonical change is detected');
select is((select fields->'companyName'->>0 from public.read_onboarding_draft(pg_temp.k(10),'company')),'A revised draft','conflict preserves saved working text');
select throws_ok($$select public.save_onboarding_draft(pg_temp.k(10),'company','{"companyName":["Stale overwrite"]}',(select base_revision from public.read_onboarding_draft(pg_temp.k(10),'company')),(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'company')))$$,'PT409',null,'draft cannot silently rebase itself');
select lives_ok($$select public.resolve_onboarding_draft(pg_temp.k(10),'company',(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'company')),true)$$,'manager explicitly chooses to keep reviewed draft');
select ok(not(select conflicted from public.read_onboarding_draft(pg_temp.k(10),'company')),'explicit resolution refreshes base authority');
select lives_ok($$select public.resolve_onboarding_draft(pg_temp.k(10),'company',(select updated_at from public.read_onboarding_draft(pg_temp.k(10),'company')),false)$$,'explicit discard uses current profile without hidden overwrite');
select lives_ok($$select public.finish_company_onboarding(pg_temp.k(10))$$,'Review finishes complete setup');
select ok((select completed_at is not null from public.onboarding_progress where organization_id=pg_temp.k(10)),'completion is durable');
select lives_ok($$select public.finish_company_onboarding(pg_temp.k(10))$$,'finish retry is idempotent');
select is((select current_step::integer from public.onboarding_progress where organization_id=pg_temp.k(10)),8,'finish never skips or advances beyond Review');
select is((select count(*)::integer from public.competitors where organization_id=pg_temp.k(10)),0,'zero competitors is valid');
select is((select count(*)::integer from public.knowledge_memories),0,'onboarding creates no automatic Memory');
select set_config('request.jwt.claim.sub',pg_temp.k(2)::text,true);
select is((select count(*)::integer from public.onboarding_drafts),0,'member cannot read private manager drafts');
select ok((select completed_at is not null from public.onboarding_progress where organization_id=pg_temp.k(10)),'invited member sees completed setup, not a repeated creator flow');
select throws_ok($$select public.save_onboarding_draft(pg_temp.k(10),'company','{}',null,null)$$,'42501',null,'MEMBER draft mutation denied');
select throws_ok($$select public.commit_onboarding_step(pg_temp.k(10),'company','{}',null,null)$$,'42501',null,'MEMBER canonical commit denied');
select throws_ok($$select public.resolve_onboarding_draft(pg_temp.k(10),'company',null,false)$$,'42501',null,'MEMBER cannot discard another manager draft');
select throws_ok($$select public.finish_company_onboarding(pg_temp.k(10))$$,'42501',null,'MEMBER cannot finish company setup');
select set_config('request.jwt.claim.sub',pg_temp.k(3)::text,true);
select throws_ok($$select public.read_onboarding_draft(pg_temp.k(10),'company')$$,'42501',null,'VIEWER draft read denied');
select throws_ok($$select public.finish_company_onboarding(pg_temp.k(10))$$,'42501',null,'VIEWER finish denied');
select throws_ok($$insert into public.onboarding_drafts(organization_id,step,fields,updated_by) values(pg_temp.k(10),'company','{}',pg_temp.k(3))$$,'42501',null,'direct draft writes cannot bypass schemas/revisions');
reset role;
select ok(not pg_catalog.has_function_privilege('anon','public.commit_onboarding_step(uuid,text,jsonb,timestamptz,timestamptz)','EXECUTE'),'anonymous commits denied');
select ok(not pg_catalog.has_function_privilege('authenticated','private.onboarding_revision(uuid,text)','EXECUTE'),'private canonical revisions are not an unscoped browser read');
select * from finish();rollback;
